-- 1. DROP EXISTING VIEWS AND TABLES
DROP VIEW IF EXISTS public.daily_updates_with_users CASCADE;
DROP VIEW IF EXISTS public.sub_units_stats CASCADE;
DROP TABLE IF EXISTS public.materials_consumption CASCADE;
DROP TABLE IF EXISTS public.daily_updates CASCADE;
DROP TABLE IF EXISTS public.marble_distribution CASCADE;
DROP TABLE IF EXISTS public.sub_units CASCADE;
DROP TABLE IF EXISTS public.tasks CASCADE;
DROP TABLE IF EXISTS public.categories CASCADE;
DROP TABLE IF EXISTS public.users CASCADE;

-- 2. CREATE TABLES WITH EXACT SCHEMAS

CREATE TABLE public.users (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email TEXT NOT NULL UNIQUE,
    password TEXT NOT NULL,
    name TEXT,
    role TEXT
);

CREATE TABLE public.categories (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL
);

CREATE TABLE public.tasks (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    category_id BIGINT REFERENCES public.categories(id) ON DELETE SET NULL,
    name TEXT NOT NULL,
    total_quantity NUMERIC,
    completed_quantity NUMERIC,
    progress_percent NUMERIC,
    unit TEXT,
    notes TEXT,
    is_manual INT DEFAULT 1
);

CREATE TABLE public.sub_units (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    task_id BIGINT REFERENCES public.tasks(id) ON DELETE CASCADE,
    serial_number INT,
    zone TEXT,
    code TEXT,
    status TEXT,
    total_quantity INT DEFAULT 1,
    notes TEXT,
    white_marked INT DEFAULT 0,
    white_extra INT DEFAULT 0,
    white_applied INT DEFAULT 0,
    white_date TEXT DEFAULT '',
    brown_marked INT DEFAULT 0,
    brown_extra INT DEFAULT 0,
    brown_applied INT DEFAULT 0,
    brown_date TEXT DEFAULT ''
);

CREATE TABLE public.marble_distribution (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    zone TEXT,
    task_name TEXT,
    white_qty INT,
    brown_qty INT,
    status TEXT
);

CREATE TABLE public.daily_updates (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id BIGINT REFERENCES public.users(id) ON DELETE SET NULL,
    sender_name TEXT,
    sender_role TEXT,
    message_text TEXT,
    media_url TEXT,
    media_type TEXT,
    reply_to_id BIGINT REFERENCES public.daily_updates(id) ON DELETE SET NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

CREATE TABLE public.materials_consumption (
    id TEXT PRIMARY KEY,
    date TEXT NOT NULL,
    day TEXT,
    start_time TEXT,
    end_time TEXT,
    prepared_by TEXT,
    basics JSONB,
    marble JSONB,
    sealants JSONB,
    bulk JSONB,
    notes TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now())
);

-- 3. CREATE VIEWS
CREATE OR REPLACE VIEW public.sub_units_stats AS
SELECT zone, status, COUNT(*)::INT as count
FROM public.sub_units
GROUP BY zone, status;

CREATE OR REPLACE VIEW public.daily_updates_with_users AS
SELECT 
    d.id, d.user_id, d.sender_name, d.sender_role, d.message_text, d.media_url, d.media_type, d.reply_to_id, d.created_at,
    u.name as user_name, u.role as user_role,
    r.sender_name as reply_sender_name, r.message_text as reply_message_text, r.media_url as reply_media_url, r.media_type as reply_media_type
FROM public.daily_updates d
LEFT JOIN public.users u ON d.user_id = u.id
LEFT JOIN public.daily_updates r ON d.reply_to_id = r.id;

